# Conscious agent — Anticipatory (stub). Reads the most recent
# observation from the World Model and decides whether to propose an
# intent. Maps subject keywords to capabilities; in production this is
# an `agent_flow` driven by a model that consults Goal Hierarchy +
# Vitals + recent Ledger to pick the right action.
env = dict(input) if isinstance(input, dict) else {"raw": input}
obs = env.get("observation") or {}
subject = (obs.get("subject") or "").lower()

intent = None
if ("wire" in subject) or ("urgent" in subject) or ("transfer" in subject):
    intent = {
        "capability": "core.transfer_funds",
        "rationale": "Subject indicates a high-stake monetary action; escalate for explicit consent.",
        "args":      {"amount": None, "recipient": None},
    }
elif ("calendar" in subject) or ("meeting" in subject) or ("reminder" in subject):
    intent = {
        "capability": "core.notify",
        "rationale": "Calendar event detected; nudge the user.",
        "args":      {"message": f"Heads up: {obs.get('subject')}"},
    }

if intent:
    env["intent"] = intent
    env.setdefault("provenance", []).append({"stage": "conscious_anticipate",
                                              "emitted_intent": intent["capability"]})
else:
    env.setdefault("provenance", []).append({"stage": "conscious_anticipate",
                                              "emitted_intent": None})
output = env
